function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  // draw flower
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  // draw bee
  ctx.beginPath();
  ctx.arc(W/2 + 70 * Math.cos(t), H/2 + 30 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 70 * Math.cos(t), H/2 + 30 * Math.sin(t), 5, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  // draw wings
  ctx.beginPath();
  ctx.moveTo(W/2 + 70 * Math.cos(t) - 10, H/2 + 30 * Math.sin(t));
  ctx.lineTo(W/2 + 70 * Math.cos(t) - 20, H/2 + 30 * Math.sin(t) - 10);
  ctx.lineTo(W/2 + 70 * Math.cos(t) - 10, H/2 + 30 * Math.sin(t) + 10);
  ctx.closePath();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70 * Math.cos(t) + 10, H/2 + 30 * Math.sin(t));
  ctx.lineTo(W/2 + 70 * Math.cos(t) + 20, H/2 + 30 * Math.sin(t) - 10);
  ctx.lineTo(W/2 + 70 * Math.cos(t) + 10, H/2 + 30 * Math.sin(t) + 10);
  ctx.closePath();
  ctx.stroke();
  ctx.restore();
}
